-- F19 Health — Interactive Workout & Rest Timers
-- Filename generated by Supabase CLI 3.1.0.
-- Git-only: production application requires explicit Gate B.

-- 1) SESSION CLOCK STATE

ALTER TABLE public.health_workout_sessions
  ADD COLUMN IF NOT EXISTS timer_paused_at timestamptz NULL,
  ADD COLUMN IF NOT EXISTS pause_accumulated_seconds integer NOT NULL DEFAULT 0
    CHECK (pause_accumulated_seconds >= 0);

-- Existing paused rows, if any, did not have F19 timing state.
-- Start counting their current pause from migration time instead of fabricating prior duration.
UPDATE public.health_workout_sessions
SET timer_paused_at = now()
WHERE status='paused'
  AND timer_paused_at IS NULL;

-- F19 may faithfully measure unusually long rest. M4's previous 1h ceiling
-- would reject the factual result even though the timer continues by design.
ALTER TABLE public.health_workout_sets
  DROP CONSTRAINT IF EXISTS health_workout_sets_rest_seconds_check;

ALTER TABLE public.health_workout_sets
  ADD CONSTRAINT health_workout_sets_rest_seconds_check
  CHECK (rest_seconds IS NULL OR (rest_seconds >= 0 AND rest_seconds <= 14400));

-- 2) PERSISTENT TIMER INTERVALS

CREATE TABLE public.health_workout_timer_intervals (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),

  athlete_id uuid NOT NULL
    REFERENCES public.health_athletes(id) ON DELETE CASCADE,

  session_id uuid NOT NULL,

  workout_exercise_id uuid NULL,

  workout_set_id uuid NULL
    REFERENCES public.health_workout_sets(id) ON DELETE SET NULL,

  interval_type text NOT NULL CHECK (
    interval_type IN ('work','rest')
  ),

  set_number integer NULL CHECK (
    set_number IS NULL OR (set_number >= 1 AND set_number <= 100)
  ),

  status text NOT NULL DEFAULT 'running' CHECK (
    status IN ('running','paused','completed','cancelled')
  ),

  target_seconds integer NULL CHECK (
    target_seconds IS NULL OR (target_seconds >= 0 AND target_seconds <= 14400)
  ),

  started_at timestamptz NOT NULL DEFAULT now(),
  paused_at timestamptz NULL,

  pause_accumulated_seconds integer NOT NULL DEFAULT 0 CHECK (
    pause_accumulated_seconds >= 0
  ),

  ended_at timestamptz NULL,

  actual_seconds integer NULL CHECK (
    actual_seconds IS NULL OR (actual_seconds >= 0 AND actual_seconds <= 86400)
  ),

  client_event_id uuid NOT NULL,

  notes text NULL,

  created_by_auth_user_id uuid NOT NULL
    REFERENCES auth.users(id) ON DELETE RESTRICT DEFAULT auth.uid(),

  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),

  UNIQUE (athlete_id, client_event_id),
  UNIQUE (id, athlete_id),

  CONSTRAINT health_workout_timer_intervals_session_athlete_fkey
    FOREIGN KEY (session_id, athlete_id)
    REFERENCES public.health_workout_sessions(id, athlete_id)
    ON DELETE CASCADE,

  CONSTRAINT health_workout_timer_intervals_exercise_session_athlete_fkey
    FOREIGN KEY (workout_exercise_id, session_id, athlete_id)
    REFERENCES public.health_workout_exercises(id, session_id, athlete_id)
    ON DELETE CASCADE,

  CHECK (
    (interval_type='work' AND workout_exercise_id IS NOT NULL AND set_number IS NOT NULL)
    OR
    (interval_type='rest' AND workout_exercise_id IS NOT NULL AND workout_set_id IS NOT NULL)
  ),

  CHECK (
    (status='running' AND paused_at IS NULL AND ended_at IS NULL AND actual_seconds IS NULL)
    OR
    (status='paused' AND paused_at IS NOT NULL AND ended_at IS NULL AND actual_seconds IS NULL)
    OR
    (status IN ('completed','cancelled') AND paused_at IS NULL AND ended_at IS NOT NULL AND actual_seconds IS NOT NULL)
  )
);

CREATE UNIQUE INDEX health_workout_timer_intervals_one_open_per_session
ON public.health_workout_timer_intervals(session_id)
WHERE status IN ('running','paused');

CREATE INDEX health_workout_timer_intervals_session_time_idx
ON public.health_workout_timer_intervals(session_id, started_at);

CREATE INDEX health_workout_timer_intervals_exercise_idx
ON public.health_workout_timer_intervals(workout_exercise_id, set_number);

CREATE TRIGGER health_workout_timer_intervals_updated_at
BEFORE UPDATE ON public.health_workout_timer_intervals
FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

-- 3) RLS — READ ONLY TO CLIENT; ALL MUTATIONS THROUGH RPCS

ALTER TABLE public.health_workout_timer_intervals ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.health_workout_timer_intervals
FROM PUBLIC, anon, authenticated;

GRANT SELECT ON public.health_workout_timer_intervals
TO authenticated;

CREATE POLICY health_workout_timer_intervals_select
ON public.health_workout_timer_intervals
FOR SELECT
TO authenticated
USING (public.health_can_read_athlete(athlete_id));

-- 4) SESSION PAUSE / RESUME

CREATE OR REPLACE FUNCTION public.health_f19_pause_workout(
  p_session_id uuid,
  p_client_event_id uuid
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_session public.health_workout_sessions%ROWTYPE;
  v_now timestamptz := clock_timestamp();
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  SELECT *
  INTO v_session
  FROM public.health_workout_sessions
  WHERE id=p_session_id
  FOR UPDATE;

  IF v_session.id IS NULL THEN
    RAISE EXCEPTION 'workout session not found';
  END IF;

  IF NOT public.health_can_write_athlete(v_session.athlete_id) THEN
    RAISE EXCEPTION 'not authorized for athlete';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.health_workout_events ev
    WHERE ev.athlete_id=v_session.athlete_id
      AND ev.client_event_id=p_client_event_id
  ) THEN
    RETURN p_session_id;
  END IF;

  IF v_session.status='paused' THEN
    RETURN p_session_id;
  END IF;

  IF v_session.status <> 'active' THEN
    RAISE EXCEPTION 'only an active workout can be paused';
  END IF;

  UPDATE public.health_workout_sessions
  SET
    status='paused',
    timer_paused_at=v_now
  WHERE id=p_session_id
    AND athlete_id=v_session.athlete_id;

  UPDATE public.health_workout_timer_intervals
  SET
    status='paused',
    paused_at=v_now
  WHERE session_id=p_session_id
    AND athlete_id=v_session.athlete_id
    AND status='running';

  INSERT INTO public.health_workout_events (
    athlete_id,
    session_id,
    event_type,
    source,
    client_event_id,
    occurred_at,
    payload,
    created_by_auth_user_id
  )
  VALUES (
    v_session.athlete_id,
    p_session_id,
    'session_paused',
    'user',
    p_client_event_id,
    v_now,
    jsonb_build_object('timer_paused_at',v_now),
    auth.uid()
  );

  RETURN p_session_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.health_f19_resume_workout(
  p_session_id uuid,
  p_client_event_id uuid
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_session public.health_workout_sessions%ROWTYPE;
  v_now timestamptz := clock_timestamp();
  v_pause_seconds integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  SELECT *
  INTO v_session
  FROM public.health_workout_sessions
  WHERE id=p_session_id
  FOR UPDATE;

  IF v_session.id IS NULL THEN
    RAISE EXCEPTION 'workout session not found';
  END IF;

  IF NOT public.health_can_write_athlete(v_session.athlete_id) THEN
    RAISE EXCEPTION 'not authorized for athlete';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.health_workout_events ev
    WHERE ev.athlete_id=v_session.athlete_id
      AND ev.client_event_id=p_client_event_id
  ) THEN
    RETURN p_session_id;
  END IF;

  IF v_session.status='active' THEN
    RETURN p_session_id;
  END IF;

  IF v_session.status <> 'paused' OR v_session.timer_paused_at IS NULL THEN
    RAISE EXCEPTION 'workout is not paused by F19 timer';
  END IF;

  v_pause_seconds := GREATEST(
    0,
    floor(extract(epoch from (v_now - v_session.timer_paused_at)))::integer
  );

  UPDATE public.health_workout_sessions
  SET
    status='active',
    pause_accumulated_seconds=pause_accumulated_seconds + v_pause_seconds,
    timer_paused_at=NULL
  WHERE id=p_session_id
    AND athlete_id=v_session.athlete_id;

  UPDATE public.health_workout_timer_intervals
  SET
    status='running',
    pause_accumulated_seconds=pause_accumulated_seconds
      + GREATEST(0, floor(extract(epoch from (v_now - paused_at)))::integer),
    paused_at=NULL
  WHERE session_id=p_session_id
    AND athlete_id=v_session.athlete_id
    AND status='paused'
    AND paused_at IS NOT NULL;

  INSERT INTO public.health_workout_events (
    athlete_id,
    session_id,
    event_type,
    source,
    client_event_id,
    occurred_at,
    payload,
    created_by_auth_user_id
  )
  VALUES (
    v_session.athlete_id,
    p_session_id,
    'session_resumed',
    'user',
    p_client_event_id,
    v_now,
    jsonb_build_object('pause_seconds',v_pause_seconds),
    auth.uid()
  );

  RETURN p_session_id;
END;
$$;

-- 5) START WORK INTERVAL

CREATE OR REPLACE FUNCTION public.health_f19_start_work_interval(
  p_workout_exercise_id uuid,
  p_client_event_id uuid
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_athlete_id uuid;
  v_session_id uuid;
  v_session_status text;
  v_exercise_status text;
  v_interval_id uuid;
  v_set_number integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  SELECT
    e.athlete_id,
    e.session_id,
    s.status,
    e.status
  INTO
    v_athlete_id,
    v_session_id,
    v_session_status,
    v_exercise_status
  FROM public.health_workout_exercises e
  JOIN public.health_workout_sessions s
    ON s.id=e.session_id
   AND s.athlete_id=e.athlete_id
  WHERE e.id=p_workout_exercise_id
  FOR UPDATE OF e, s;

  IF v_athlete_id IS NULL THEN
    RAISE EXCEPTION 'workout exercise not found';
  END IF;

  IF NOT public.health_can_write_athlete(v_athlete_id) THEN
    RAISE EXCEPTION 'not authorized for athlete';
  END IF;

  SELECT t.id
  INTO v_interval_id
  FROM public.health_workout_timer_intervals t
  WHERE t.athlete_id=v_athlete_id
    AND t.client_event_id=p_client_event_id
  LIMIT 1;

  IF v_interval_id IS NOT NULL THEN
    RETURN v_interval_id;
  END IF;

  IF v_session_status <> 'active' THEN
    RAISE EXCEPTION 'workout must be active to start execution timer';
  END IF;

  IF v_exercise_status NOT IN ('pending','active') THEN
    RAISE EXCEPTION 'exercise is not available for execution';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.health_workout_timer_intervals t
    WHERE t.session_id=v_session_id
      AND t.athlete_id=v_athlete_id
      AND t.status IN ('running','paused')
  ) THEN
    RAISE EXCEPTION 'another workout timer is already open';
  END IF;

  SELECT coalesce(max(ws.set_number),0)+1
  INTO v_set_number
  FROM public.health_workout_sets ws
  WHERE ws.workout_exercise_id=p_workout_exercise_id
    AND ws.athlete_id=v_athlete_id
    AND ws.status='completed';

  INSERT INTO public.health_workout_timer_intervals (
    athlete_id,
    session_id,
    workout_exercise_id,
    interval_type,
    set_number,
    status,
    client_event_id,
    created_by_auth_user_id
  )
  VALUES (
    v_athlete_id,
    v_session_id,
    p_workout_exercise_id,
    'work',
    v_set_number,
    'running',
    p_client_event_id,
    auth.uid()
  )
  RETURNING id INTO v_interval_id;

  UPDATE public.health_workout_exercises
  SET status='active'
  WHERE id=p_workout_exercise_id
    AND athlete_id=v_athlete_id
    AND status='pending';

  RETURN v_interval_id;
END;
$$;

-- 6) FINISH WORK + REGISTER SET + START REST

CREATE OR REPLACE FUNCTION public.health_f19_finish_work_start_rest(
  p_work_interval_id uuid,
  p_client_event_id uuid,
  p_load_value numeric DEFAULT NULL,
  p_load_unit text DEFAULT 'kg',
  p_reps integer DEFAULT NULL,
  p_rir numeric DEFAULT NULL
)
RETURNS TABLE (
  workout_set_id uuid,
  rest_interval_id uuid
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_interval public.health_workout_timer_intervals%ROWTYPE;
  v_session_status text;
  v_planned_rest integer;
  v_now timestamptz := clock_timestamp();
  v_work_seconds integer;
  v_set_id uuid;
  v_rest_id uuid;
  v_existing_event public.health_workout_events%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  SELECT *
  INTO v_interval
  FROM public.health_workout_timer_intervals
  WHERE id=p_work_interval_id
  FOR UPDATE;

  IF v_interval.id IS NULL THEN
    RAISE EXCEPTION 'work timer not found';
  END IF;

  IF NOT public.health_can_write_athlete(v_interval.athlete_id) THEN
    RAISE EXCEPTION 'not authorized for athlete';
  END IF;

  SELECT *
  INTO v_existing_event
  FROM public.health_workout_events ev
  WHERE ev.athlete_id=v_interval.athlete_id
    AND ev.client_event_id=p_client_event_id
    AND ev.event_type='set_logged'
  LIMIT 1;

  IF v_existing_event.id IS NOT NULL THEN
    RETURN QUERY
    SELECT
      v_existing_event.workout_set_id,
      NULLIF(v_existing_event.payload->>'rest_interval_id','')::uuid;
    RETURN;
  END IF;

  SELECT s.status, e.planned_rest_seconds
  INTO v_session_status, v_planned_rest
  FROM public.health_workout_sessions s
  JOIN public.health_workout_exercises e
    ON e.id=v_interval.workout_exercise_id
   AND e.session_id=s.id
   AND e.athlete_id=s.athlete_id
  WHERE s.id=v_interval.session_id
    AND s.athlete_id=v_interval.athlete_id
  FOR UPDATE OF s, e;

  IF v_session_status <> 'active' THEN
    RAISE EXCEPTION 'workout must be active to finish a set';
  END IF;

  IF v_interval.interval_type <> 'work' OR v_interval.status <> 'running' THEN
    RAISE EXCEPTION 'work timer is not running';
  END IF;

  v_work_seconds := GREATEST(
    0,
    floor(
      extract(epoch from (v_now - v_interval.started_at))
      - v_interval.pause_accumulated_seconds
    )::integer
  );

  INSERT INTO public.health_workout_sets (
    workout_exercise_id,
    session_id,
    athlete_id,
    set_number,
    set_type,
    status,
    load_value,
    load_unit,
    reps,
    rir,
    rest_seconds,
    client_event_id,
    completed_at,
    notes
  )
  VALUES (
    v_interval.workout_exercise_id,
    v_interval.session_id,
    v_interval.athlete_id,
    v_interval.set_number,
    'working',
    'completed',
    p_load_value,
    COALESCE(NULLIF(p_load_unit,''),'kg'),
    p_reps,
    p_rir,
    NULL,
    p_client_event_id,
    v_now,
    CASE
      WHEN p_load_value IS NULL AND p_reps IS NULL AND p_rir IS NULL
      THEN 'F19_TIMING_ONLY: desempenho não informado; tempo factual preservado.'
      ELSE 'F19_INTERACTIVE_TIMER'
    END
  )
  RETURNING id INTO v_set_id;

  UPDATE public.health_workout_timer_intervals
  SET
    status='completed',
    ended_at=v_now,
    actual_seconds=v_work_seconds,
    workout_set_id=v_set_id,
    paused_at=NULL
  WHERE id=v_interval.id
    AND athlete_id=v_interval.athlete_id;

  INSERT INTO public.health_workout_timer_intervals (
    athlete_id,
    session_id,
    workout_exercise_id,
    workout_set_id,
    interval_type,
    set_number,
    status,
    target_seconds,
    client_event_id,
    created_by_auth_user_id
  )
  VALUES (
    v_interval.athlete_id,
    v_interval.session_id,
    v_interval.workout_exercise_id,
    v_set_id,
    'rest',
    v_interval.set_number,
    'running',
    v_planned_rest,
    gen_random_uuid(),
    auth.uid()
  )
  RETURNING id INTO v_rest_id;

  INSERT INTO public.health_workout_events (
    athlete_id,
    session_id,
    workout_exercise_id,
    workout_set_id,
    event_type,
    source,
    client_event_id,
    occurred_at,
    payload,
    created_by_auth_user_id
  )
  VALUES (
    v_interval.athlete_id,
    v_interval.session_id,
    v_interval.workout_exercise_id,
    v_set_id,
    'set_logged',
    'user',
    p_client_event_id,
    v_now,
    jsonb_build_object(
      'set_number',v_interval.set_number,
      'set_type','working',
      'load_value',p_load_value,
      'load_unit',COALESCE(NULLIF(p_load_unit,''),'kg'),
      'reps',p_reps,
      'rir',p_rir,
      'rest_seconds',NULL,
      'work_seconds',v_work_seconds,
      'work_interval_id',v_interval.id,
      'rest_interval_id',v_rest_id,
      'timing_only',(p_load_value IS NULL AND p_reps IS NULL AND p_rir IS NULL)
    ),
    auth.uid()
  );

  RETURN QUERY SELECT v_set_id, v_rest_id;
END;
$$;

-- 7) FINISH REST, OPTIONALLY START NEXT WORK INTERVAL

CREATE OR REPLACE FUNCTION public.health_f19_finish_rest(
  p_rest_interval_id uuid,
  p_client_event_id uuid,
  p_start_next_work boolean DEFAULT false,
  p_next_workout_exercise_id uuid DEFAULT NULL
)
RETURNS TABLE (
  rest_interval_id uuid,
  next_work_interval_id uuid
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_rest public.health_workout_timer_intervals%ROWTYPE;
  v_session_status text;
  v_now timestamptz := clock_timestamp();
  v_rest_seconds integer;
  v_extra_seconds integer;
  v_next_exercise_id uuid;
  v_next_status text;
  v_next_set_number integer;
  v_next_interval_id uuid := NULL;
  v_existing_event public.health_workout_events%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  SELECT *
  INTO v_rest
  FROM public.health_workout_timer_intervals
  WHERE id=p_rest_interval_id
  FOR UPDATE;

  IF v_rest.id IS NULL THEN
    RAISE EXCEPTION 'rest timer not found';
  END IF;

  IF NOT public.health_can_write_athlete(v_rest.athlete_id) THEN
    RAISE EXCEPTION 'not authorized for athlete';
  END IF;

  SELECT *
  INTO v_existing_event
  FROM public.health_workout_events ev
  WHERE ev.athlete_id=v_rest.athlete_id
    AND ev.client_event_id=p_client_event_id
    AND ev.event_type='rest_recorded'
  LIMIT 1;

  IF v_existing_event.id IS NOT NULL THEN
    RETURN QUERY
    SELECT
      p_rest_interval_id,
      NULLIF(v_existing_event.payload->>'next_work_interval_id','')::uuid;
    RETURN;
  END IF;

  SELECT s.status
  INTO v_session_status
  FROM public.health_workout_sessions s
  WHERE s.id=v_rest.session_id
    AND s.athlete_id=v_rest.athlete_id
  FOR UPDATE;

  IF v_session_status <> 'active' THEN
    RAISE EXCEPTION 'workout must be active to finish rest';
  END IF;

  IF v_rest.interval_type <> 'rest' OR v_rest.status <> 'running' THEN
    RAISE EXCEPTION 'rest timer is not running';
  END IF;

  v_rest_seconds := GREATEST(
    0,
    floor(
      extract(epoch from (v_now - v_rest.started_at))
      - v_rest.pause_accumulated_seconds
    )::integer
  );

  v_extra_seconds := CASE
    WHEN v_rest.target_seconds IS NULL THEN 0
    ELSE GREATEST(0, v_rest_seconds - v_rest.target_seconds)
  END;

  UPDATE public.health_workout_timer_intervals
  SET
    status='completed',
    ended_at=v_now,
    actual_seconds=v_rest_seconds,
    paused_at=NULL
  WHERE id=v_rest.id
    AND athlete_id=v_rest.athlete_id;

  UPDATE public.health_workout_sets
  SET rest_seconds=v_rest_seconds
  WHERE id=v_rest.workout_set_id
    AND athlete_id=v_rest.athlete_id;

  IF p_start_next_work THEN
    v_next_exercise_id := COALESCE(
      p_next_workout_exercise_id,
      v_rest.workout_exercise_id
    );

    SELECT e.status
    INTO v_next_status
    FROM public.health_workout_exercises e
    WHERE e.id=v_next_exercise_id
      AND e.session_id=v_rest.session_id
      AND e.athlete_id=v_rest.athlete_id
    FOR UPDATE;

    IF v_next_status IS NULL THEN
      RAISE EXCEPTION 'next workout exercise not found in this session';
    END IF;

    IF v_next_status NOT IN ('pending','active') THEN
      RAISE EXCEPTION 'next workout exercise is not available';
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.health_workout_timer_intervals t
      WHERE t.session_id=v_rest.session_id
        AND t.athlete_id=v_rest.athlete_id
        AND t.status IN ('running','paused')
    ) THEN
      RAISE EXCEPTION 'another workout timer is already open';
    END IF;

    SELECT coalesce(max(ws.set_number),0)+1
    INTO v_next_set_number
    FROM public.health_workout_sets ws
    WHERE ws.workout_exercise_id=v_next_exercise_id
      AND ws.athlete_id=v_rest.athlete_id
      AND ws.status='completed';

    INSERT INTO public.health_workout_timer_intervals (
      athlete_id,
      session_id,
      workout_exercise_id,
      interval_type,
      set_number,
      status,
      client_event_id,
      created_by_auth_user_id
    )
    VALUES (
      v_rest.athlete_id,
      v_rest.session_id,
      v_next_exercise_id,
      'work',
      v_next_set_number,
      'running',
      gen_random_uuid(),
      auth.uid()
    )
    RETURNING id INTO v_next_interval_id;

    UPDATE public.health_workout_exercises
    SET status='active'
    WHERE id=v_next_exercise_id
      AND athlete_id=v_rest.athlete_id
      AND status='pending';
  END IF;

  INSERT INTO public.health_workout_events (
    athlete_id,
    session_id,
    workout_exercise_id,
    workout_set_id,
    event_type,
    source,
    client_event_id,
    occurred_at,
    payload,
    created_by_auth_user_id
  )
  VALUES (
    v_rest.athlete_id,
    v_rest.session_id,
    v_rest.workout_exercise_id,
    v_rest.workout_set_id,
    'rest_recorded',
    'user',
    p_client_event_id,
    v_now,
    jsonb_build_object(
      'rest_interval_id',v_rest.id,
      'actual_seconds',v_rest_seconds,
      'target_seconds',v_rest.target_seconds,
      'extra_seconds',v_extra_seconds,
      'next_work_interval_id',v_next_interval_id
    ),
    auth.uid()
  );

  RETURN QUERY SELECT v_rest.id, v_next_interval_id;
END;
$$;

-- 8) CANCEL OPEN INTERVAL WITHOUT INVENTING PERFORMANCE

CREATE OR REPLACE FUNCTION public.health_f19_cancel_interval(
  p_interval_id uuid,
  p_client_event_id uuid
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_interval public.health_workout_timer_intervals%ROWTYPE;
  v_now timestamptz := clock_timestamp();
  v_current_pause_seconds integer := 0;
  v_actual_seconds integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  SELECT *
  INTO v_interval
  FROM public.health_workout_timer_intervals
  WHERE id=p_interval_id
  FOR UPDATE;

  IF v_interval.id IS NULL THEN
    RAISE EXCEPTION 'timer interval not found';
  END IF;

  IF NOT public.health_can_write_athlete(v_interval.athlete_id) THEN
    RAISE EXCEPTION 'not authorized for athlete';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.health_workout_events ev
    WHERE ev.athlete_id=v_interval.athlete_id
      AND ev.client_event_id=p_client_event_id
  ) THEN
    RETURN p_interval_id;
  END IF;

  IF v_interval.status IN ('completed','cancelled') THEN
    RETURN p_interval_id;
  END IF;

  IF v_interval.status='paused' AND v_interval.paused_at IS NOT NULL THEN
    v_current_pause_seconds := GREATEST(
      0,
      floor(extract(epoch from (v_now - v_interval.paused_at)))::integer
    );
  END IF;

  v_actual_seconds := GREATEST(
    0,
    floor(
      extract(epoch from (v_now - v_interval.started_at))
      - v_interval.pause_accumulated_seconds
      - v_current_pause_seconds
    )::integer
  );

  UPDATE public.health_workout_timer_intervals
  SET
    status='cancelled',
    paused_at=NULL,
    ended_at=v_now,
    actual_seconds=v_actual_seconds
  WHERE id=p_interval_id
    AND athlete_id=v_interval.athlete_id;

  INSERT INTO public.health_workout_events (
    athlete_id,
    session_id,
    workout_exercise_id,
    workout_set_id,
    event_type,
    source,
    client_event_id,
    occurred_at,
    payload,
    created_by_auth_user_id
  )
  VALUES (
    v_interval.athlete_id,
    v_interval.session_id,
    v_interval.workout_exercise_id,
    v_interval.workout_set_id,
    'note',
    'user',
    p_client_event_id,
    v_now,
    jsonb_build_object(
      'kind','F19_TIMER_CANCELLED',
      'interval_id',v_interval.id,
      'interval_type',v_interval.interval_type,
      'actual_seconds',v_actual_seconds
    ),
    auth.uid()
  );

  RETURN p_interval_id;
END;
$$;

-- 9) DEFENSIVE CLEANUP WHEN M4 COMPLETES/ABORTS A SESSION OUTSIDE F19

CREATE OR REPLACE FUNCTION public.health_f19_close_open_timers_with_session()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_now timestamptz := clock_timestamp();
BEGIN
  IF NEW.status IN ('completed','aborted')
     AND OLD.status IS DISTINCT FROM NEW.status THEN

    UPDATE public.health_workout_timer_intervals t
    SET
      status='cancelled',
      ended_at=v_now,
      actual_seconds=GREATEST(
        0,
        floor(
          extract(
            epoch from (
              CASE
                WHEN t.status='paused' AND t.paused_at IS NOT NULL
                THEN t.paused_at
                ELSE v_now
              END
              - t.started_at
            )
          )
          - t.pause_accumulated_seconds
        )::integer
      ),
      paused_at=NULL
    WHERE t.session_id=NEW.id
      AND t.athlete_id=NEW.athlete_id
      AND t.status IN ('running','paused');

  END IF;

  RETURN NEW;
END;
$$;

CREATE TRIGGER health_f19_close_open_timers_with_session
AFTER UPDATE OF status ON public.health_workout_sessions
FOR EACH ROW
EXECUTE FUNCTION public.health_f19_close_open_timers_with_session();

-- 10) FUNCTION PERMISSIONS

REVOKE ALL ON FUNCTION public.health_f19_pause_workout(uuid, uuid)
FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.health_f19_resume_workout(uuid, uuid)
FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.health_f19_start_work_interval(uuid, uuid)
FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.health_f19_finish_work_start_rest(uuid, uuid, numeric, text, integer, numeric)
FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.health_f19_finish_rest(uuid, uuid, boolean, uuid)
FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.health_f19_cancel_interval(uuid, uuid)
FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.health_f19_close_open_timers_with_session()
FROM PUBLIC, anon, authenticated;

GRANT EXECUTE ON FUNCTION public.health_f19_pause_workout(uuid, uuid)
TO authenticated;
GRANT EXECUTE ON FUNCTION public.health_f19_resume_workout(uuid, uuid)
TO authenticated;
GRANT EXECUTE ON FUNCTION public.health_f19_start_work_interval(uuid, uuid)
TO authenticated;
GRANT EXECUTE ON FUNCTION public.health_f19_finish_work_start_rest(uuid, uuid, numeric, text, integer, numeric)
TO authenticated;
GRANT EXECUTE ON FUNCTION public.health_f19_finish_rest(uuid, uuid, boolean, uuid)
TO authenticated;
GRANT EXECUTE ON FUNCTION public.health_f19_cancel_interval(uuid, uuid)
TO authenticated;

-- Trigger helper is intentionally not callable by authenticated clients.

-- End F19 v1.
